<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Request status</title>@vite(['resources/css/app.css','resources/js/app.js'])</head><body class="bg-slate-100 text-slate-900"><main class="mx-auto max-w-2xl px-4 py-10"><a href="{{ route('request.create') }}" class="text-sm font-semibold text-indigo-600">&larr; New request</a><h1 class="mt-5 text-3xl font-bold">Check request status</h1><form method="POST" action="{{ route('request.status.check') }}" class="mt-6 grid gap-4 rounded-xl bg-white p-6 shadow-sm ring-1 ring-slate-200 sm:grid-cols-2">@csrf<div><label class="block text-sm font-medium">Tracking code</label><input name="tracking_code" value="{{ old('tracking_code') }}" class="mt-1 w-full rounded-lg border-slate-300"></div><div><label class="block text-sm font-medium">Or phone number</label><input name="employee_phone" value="{{ old('employee_phone') }}" class="mt-1 w-full rounded-lg border-slate-300"></div><button class="rounded-lg bg-indigo-600 px-4 py-3 font-semibold text-white sm:col-span-2">Find request</button></form>@if(isset($requests))<div class="mt-8 space-y-3">@forelse($requests as $request)<article class="rounded-xl bg-white p-5 shadow-sm ring-1 ring-slate-200"><div class="flex flex-wrap justify-between gap-2"><strong>{{ $request->tracking_code }}</strong><span class="rounded-full bg-indigo-50 px-3 py-1 text-sm font-semibold text-indigo-700">{{ $request->status }}</span></div><p class="mt-3 text-slate-600">{{ $request->item->name }} &middot; {{ $request->quantity }} {{ $request->item->unit }}</p><p class="mt-1 text-sm text-slate-500">Submitted {{ $request->created_at->format('d M Y, H:i') }}</p>@if($request->rejected_reason)<p class="mt-3 text-sm text-red-700">Reason: {{ $request->rejected_reason }}</p>@endif</article>@empty<p class="rounded-lg bg-amber-50 p-4 text-amber-800">No matching requests found.</p>@endforelse</div>@endif</main></body></html>
